#include <vector>

std::vector<int> merge(const std::vector<int>& left, const std::vector<int>& right)
{
    std::vector<int> result{};
    result.reserve(left.size() + right.size());
    std::size_t i{ 0 };
    std::size_t j{ 0 };
    while (i < left.size() && j < right.size())
    {
        if (left[i] <= right[j]) result.push_back(left[i++]);
        else result.push_back(right[j++]);
    }
    while (i < left.size()) result.push_back(left[i++]);
    while (j < right.size()) result.push_back(right[j++]);
    return result;
}

std::vector<int> mergeSort(const std::vector<int>& values)
{
    if (values.size() <= 1)
    {
        return values;
    }
    const auto middle{ values.begin() + static_cast<std::ptrdiff_t>(values.size() / 2) };
    const std::vector<int> left{ mergeSort(std::vector<int>(values.begin(), middle)) };
    const std::vector<int> right{ mergeSort(std::vector<int>(middle, values.end())) };
    return merge(left, right);
}

unitTests:
TEST("merge two sorted vectors") { CHECK_EQ(merge({ 1, 4, 9 }, { 2, 3, 10, 11 }), (std::vector<int>{ 1, 2, 3, 4, 9, 10, 11 })); }
TEST("merge with an empty side") { CHECK_EQ(merge({}, { 1, 2 }), (std::vector<int>{ 1, 2 })); CHECK_EQ(merge({ 5 }, {}), (std::vector<int>{ 5 })); }
TEST("mergeSort") { CHECK_EQ(mergeSort({ 8, 3, 5, 1, 9, 2, 7 }), (std::vector<int>{ 1, 2, 3, 5, 7, 8, 9 })); }
TEST("duplicates, empty, single") { CHECK_EQ(mergeSort({ 2, 1, 2, 1 }), (std::vector<int>{ 1, 1, 2, 2 })); CHECK(mergeSort({}).empty()); CHECK_EQ(mergeSort({ 4 }), (std::vector<int>{ 4 })); }
TEST("fast on 200,000 elements") { std::vector<int> big(200000); unsigned x{ 12345 }; for (auto& v : big) { x = x * 1103515245u + 12345u; v = static_cast<int>(x >> 8); } const auto sorted{ mergeSort(big) }; bool ok{ sorted.size() == big.size() }; for (std::size_t i{ 1 }; i < sorted.size(); ++i) if (sorted[i - 1] > sorted[i]) ok = false; CHECK(ok); }

